172. func stringToHeader(value string) map[string]string {
173. 	headersPairs := strings.Split(value, ",")
174. 	headers := make(map[string]string)
175. 
176. 	for _, header := range headersPairs {
177. 		nameValue := strings.SplitN(header, "=", 2)
178. 		if len(nameValue) < 2 {
179. 			continue
180. 		}
181. 		name, err := url.QueryUnescape(nameValue[0])
182. 		if err != nil {
