186. 		value, err := url.QueryUnescape(nameValue[1])
187. 		if err != nil {
188. 			continue
189. 		}
190. 		trimmedValue := strings.TrimSpace(value)
191. 
192. 		headers[trimmedName] = trimmedValue
193. 	}
194. 
195. 	return headers
196. }
