414. func sumPoint(record export.Record, num number.Number, start, end time.Time, ek export.ExportKind, monotonic bool) (*metricpb.Metric, error) {
415. 	desc := record.Descriptor()
416. 	labels := record.Labels()
417. 
418. 	m := &metricpb.Metric{
419. 		Name:        desc.Name(),
420. 		Description: desc.Description(),
421. 		Unit:        string(desc.Unit()),
422. 	}
423. 
424. 	switch n := desc.NumberKind(); n {
425. 	case number.Int64Kind:
426. 		m.Data = &metricpb.Metric_IntSum{
427. 			IntSum: &metricpb.IntSum{
428. 				IsMonotonic:            monotonic,
429. 				AggregationTemporality: exportKindToTemporality(ek),
430. 				DataPoints: []*metricpb.IntDataPoint{
431. 					{
432. 						Value:             num.CoerceToInt64(n),
433. 						Labels:            stringKeyValues(labels.Iter()),
434. 						StartTimeUnixNano: toNanos(start),
435. 						TimeUnixNano:      toNanos(end),
436. 					},
437. 				},
438. 			},
439. 		}
440. 	case number.Float64Kind:
441. 		m.Data = &metricpb.Metric_DoubleSum{
442. 			DoubleSum: &metricpb.DoubleSum{
443. 				IsMonotonic:            monotonic,
444. 				AggregationTemporality: exportKindToTemporality(ek),
445. 				DataPoints: []*metricpb.DoubleDataPoint{
446. 					{
447. 						Value:             num.CoerceToFloat64(n),
448. 						Labels:            stringKeyValues(labels.Iter()),
449. 						StartTimeUnixNano: toNanos(start),
450. 						TimeUnixNano:      toNanos(end),
451. 					},
452. 				},
453. 			},
454. 		}
455. 	default:
456. 		return nil, fmt.Errorf("%w: %v", ErrUnknownValueType, n)
457. 	}
