462. // minMaxSumCountValue returns the values of the MinMaxSumCount Aggregator
463. // as discrete values.
464. func minMaxSumCountValues(a aggregation.MinMaxSumCount) (min, max, sum number.Number, count uint64, err error) {
465. 	if min, err = a.Min(); err != nil {
466. 		return
467. 	}
468. 	if max, err = a.Max(); err != nil {
469. 		return
470. 	}
471. 	if sum, err = a.Sum(); err != nil {
472. 		return
473. 	}
474. 	if count, err = a.Count(); err != nil {
475. 		return
476. 	}
477. 	return
478. }
