480. // minMaxSumCount transforms a MinMaxSumCount Aggregator into an OTLP Metric.
481. func minMaxSumCount(record export.Record, a aggregation.MinMaxSumCount) (*metricpb.Metric, error) {
482. 	desc := record.Descriptor()
483. 	labels := record.Labels()
